import { ObserversModule } from '@angular/cdk/observers';
import {
  ChangeDetectionStrategy,
  Component,
  HostListener,
  inject,
  input,
  signal,
  viewChild,
} from '@angular/core';
import { MatRipple } from '@angular/material/core';
import { MatTooltip, MatTooltipModule } from '@angular/material/tooltip';

import { SatPlatformNavInitials } from '../../platform-nav-initials';
import { SatPlatformNavState } from '../../services/platform-nav-state';
import { SatPlatformNavTooltip } from '../../services/platform-nav-tooltip';
import { SatPlatformNavAppIcon } from '../platform-nav-app-icon/platform-nav-app-icon';

/**
 * This element represents an interactive item within the `sat-platform-nav` navigation panel. It supports icons, dynamic avatar generation, active state styling, and responsive behavior based on the collapsed state of the sidebar.
 *
 * The `SatPlatformNavListItem` is designed to display a single item in the platform navigation.
 *
 * Key features:
 * - Accepts a projected mat-icon for visual representation of the item.
 * - Automatically generates a fallback avatar (initials-based) if no icon is present, using the SatPlatformNavListItemInitialsPipe applied to the item’s label.
 * - Hides the text label when the navigation panel is collapsed, using SatPlatformNavService.
 * - Allows keyboard accessibility supporting navigation via keyboard.
 *
 * @deprecated This component supports a deprecated usage pattern where content is projected for displaying the icon or avatar.
 * The use of mat-icon is deprecated and will be removed in future versions. Prefer using `<sat-platform-nav-avatar>` with the `item` input for avatar rendering.
 *
 * Deprecated usage: Icon render via mat-icon is deprecated.
 */
@Component({
  selector: 'sat-platform-nav-list-item',
  // a11y: In the absence of a `href`, <a> elements are treated as a group role, to avoid this, we set role="link" explicitly.
  template: `
    <a
      matRipple
      matRippleColor="var(--sat-sys-on-primary-opacity-12)"
      class="sat-platform-nav-item"
      tabIndex="0"
      [class.sat-platform-nav-item-active]="active()"
      [matTooltip]="labelText() ?? label.innerText"
      matTooltipPosition="right"
      matTooltipDisabled="true"
      #tooltip="matTooltip"
      [attr.aria-label]="labelText() ?? label.innerText"
      [attr.href]="url() ?? null"
      role="link"
      (focus)="onMouseEnter()"
      (blur)="onMouseLeave()"
    >
      <div class="sat-platform-nav-icon">
        <ng-container #iconContainer>
          <!-- @deprecated Rendering mat-icon here is deprecated and would be removed in future versions. Please use <sat-platform-nav-avatar> instead with the proper inputs -->
          <!-- TODO: Remove mat-icon for https://hyland.atlassian.net/browse/DS-783 -->
          <ng-content select="mat-icon, sat-platform-nav-avatar"></ng-content>
        </ng-container>
        @if (
          iconContainer?.previousElementSibling?.localName !== 'mat-icon' &&
          iconContainer?.previousElementSibling?.localName !== 'sat-platform-nav-avatar'
        ) {
          <sat-platform-nav-app-icon>
            {{ labelText() ?? label.innerText | satPlatformNavInitials }}
          </sat-platform-nav-app-icon>
        }
      </div>
      <p #label
        class="sat-platform-nav-item-label"
        [class.sat-platform-nav-hidden]="service.collapsed()"
        (cdkObserveContent)="labelChanged($event)"
        >
        <ng-content></ng-content>
      </p>
    </a>
  `,
  imports: [
    MatRipple,
    SatPlatformNavAppIcon,
    MatTooltipModule,
    SatPlatformNavInitials,
    ObserversModule,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class SatPlatformNavListItem {
  /** The URL to navigate to when the item is clicked. */
  readonly url = input<string>();
  /**
   * Determines whether the list item should be rendered in an active/selected state.
   */
  readonly active = input<boolean>(false);

  /**
   * @internal
   * The text content of the label, used for tooltip and fallback initials.
   */
  readonly labelText = signal<string | undefined>(undefined);

  /** @internal */
  readonly service = inject(SatPlatformNavState);

  private readonly tooltipService = inject(SatPlatformNavTooltip);

  private readonly tooltip = viewChild<MatTooltip>('tooltip');

  private readonly tooltipDelay = 600;
  private tooltipTimer: ReturnType<typeof setTimeout> | null = null;

  /** @internal */
  @HostListener('mouseenter')
  onMouseEnter() {
    if (this.service.collapsed()) {
      const currentTooltip = this.tooltip();
      const previousTooltip = this.tooltipService.activateTooltip;
      if (!currentTooltip) {
        return;
      }
      if (previousTooltip && previousTooltip !== currentTooltip) {
        this.hidePreviousTooltip(previousTooltip);
      }

      const delayTime = this.tooltipService.tooltipShownFirst() ? 0 : this.tooltipDelay;

      if (delayTime) {
        this.tooltipTimer = setTimeout(() => {
          this.showCurrentTooltip(currentTooltip);
          this.tooltipService.updateTooltipShownFirst(true);
        }, delayTime);
      } else {
        this.showCurrentTooltip(currentTooltip);
      }
    }
  }

  /** @internal */
  @HostListener('mouseleave')
  onMouseLeave() {
    if (this.tooltipTimer) {
      clearTimeout(this.tooltipTimer);
      this.tooltipTimer = null;
    }
    const currentTooltip = this.tooltip();
    if (currentTooltip && this.tooltipService.activateTooltip === currentTooltip) {
      this.hidePreviousTooltip(this.tooltipService.activateTooltip);
    }
  }

  /** @internal */
  labelChanged(event: MutationRecord[]): void {
    const text = event[0]?.target?.textContent;
    if (text) {
      this.labelText.set(text);
    }
  }

  private hidePreviousTooltip(previousTooltip: MatTooltip): void {
    previousTooltip.disabled = true;
    previousTooltip.hide();
    this.tooltipService.updateActiveTooltip(null);
  }

  private showCurrentTooltip(tooltip: MatTooltip): void {
    this.tooltipService.updateActiveTooltip(tooltip);
    tooltip.disabled = false;
    tooltip.show();
  }
}
