import { ChangeDetectionStrategy, Component, computed, input } from '@angular/core';
import { MatIconModule } from '@angular/material/icon';

import { SatPlatformNavInitials } from '../../platform-nav-initials';
import {
  SatNavigationItem,
  SatNavigationItemWithIcon,
  SatNavigationItemWithImage,
} from '../../types/platform-nav-item.type';
import { SatPlatformNavAppIcon } from '../platform-nav-app-icon/platform-nav-app-icon';

/**
 * The `SatPlatformNavAvatar` displays an avatar in the platform navigation.
 * It supports rendering an icon, image, or initials based on the provided navigation item.
 *
 * - If the navigation item has an `icon`, it renders a Material icon.
 * - If the navigation item has an `image`, it renders the image inside a custom app icon component.
 * - Otherwise, it renders the initials derived from the navigation item's label.
 *
 * @deprecated This component supports a deprecated usage pattern where content is projected via <ng-content>.
 *
 * Prefer passing a `SatNavigationItem` via the `item` input for avatar rendering.
 */
@Component({
  selector: 'sat-platform-nav-avatar',
  host: {
    class: 'sat-platform-nav-avatar',
  },
  template: `
    @if(item(); as navItem) {
      @if (icon()) {
        <mat-icon svgIcon="{{ icon() }}"></mat-icon>
      } @else if (image()) {
        <sat-platform-nav-app-icon>
          <img [src]="image()" [alt]="navItem.label" />
        </sat-platform-nav-app-icon>
      } @else {
        <sat-platform-nav-app-icon>{{ navItem.label | satPlatformNavInitials }}</sat-platform-nav-app-icon>
      }
    } @else {
      <!-- @deprecated: Content projection via <ng-content> is deprecated. Use the [item] input instead. -->
      <!-- TODO: Remove this for https://hyland.atlassian.net/browse/DS-783 -->
      <span class="sat-platform-nav-app-icon">
        <ng-content></ng-content>
      </span>
    }
  `,
  imports: [MatIconModule, SatPlatformNavAppIcon, SatPlatformNavInitials],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class SatPlatformNavAvatar {
  // TODO: Make this input "required" for https://hyland.atlassian.net/browse/DS-783
  /**
   * The navigation item associated with this avatar.
   */
  readonly item = input<SatNavigationItem>();

  /** @internal */
  readonly icon = computed(() => {
    const item = this.item();
    return item && this.itemIsSatNavigationItemWithIcon(item) ? item.icon : null;
  });

  /** @internal */
  readonly image = computed(() => {
    const item = this.item();
    return item && this.itemIsSatNavigationItemWithImage(item) ? item.image : null;
  });

  private itemIsSatNavigationItemWithIcon(
    item: SatNavigationItem,
  ): item is SatNavigationItemWithIcon {
    return 'icon' in item && typeof item.icon === 'string';
  }

  private itemIsSatNavigationItemWithImage(
    item: SatNavigationItem,
  ): item is SatNavigationItemWithImage {
    return 'image' in item && typeof item.image === 'string';
  }
}
