import { ChangeDetectionStrategy, Component } from '@angular/core';

/**
 * This serves as a container for user-related UI elements within the navigation. It wraps the `SatPlatformNavUserProfile` and provides a slot (`satPlatformNavUserMenu`) for displaying a user menu, typically with dynamic items such as languages or logout options. This component ensures consistent layout and behavior for the user section in the navigation.
 *
 * Key features:
 * - Acts as the container for the user interaction section in the sidebar.
 * - Typically positioned at the bottom of the nav, separating navigation from account-related actions.
 * - Can act as a menu trigger using `[matMenuTriggerFor]`.
 *
 * @example
 * <sat-platform-nav-user>
 *   <button satPlatformNavUserProfile [matMenuTriggerFor]="userMenu">
 *     Lorem Ipsum
 *   </button>
 *   <mat-menu #userMenu="matMenu" satPlatformNavUserMenu>
 *     <button mat-menu-item>
 *       …
 *     </button>
 *   </mat-menu>
 * </sat-platform-nav-user>
 */
@Component({
  selector: 'sat-platform-nav-user',
  template: `
    <div class="sat-platform-nav-user">
      <ng-content select="sat-platform-nav-user-profile, button[satPlatformNavUserProfile]"></ng-content>
    </div>
    <ng-content select="[satPlatformNavUserMenu]"></ng-content>
  `,
  styleUrl: './platform-nav-user.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class SatPlatformNavUser {}
