import { CdkMenuModule } from '@angular/cdk/menu';
import {
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  inject,
  input,
  linkedSignal,
  output,
} from '@angular/core';
import { MatButtonModule } from '@angular/material/button';
import { MatRipple } from '@angular/material/core';
import { MatIconModule } from '@angular/material/icon';
import { MatTooltip } from '@angular/material/tooltip';
import { TranslatePipe } from '@ngx-translate/core';

import { SatPlatformNavEnvironmentType, SatPlatformNavState } from '../../public-api';
import { SatPlatformNavEnvironmentSwitcherItem } from './platform-nav-environment-switcher-item';

/**
 * This component is used to display a switcher which allows the user to switch between different environments within the Platform Nav. It allows users to select their current working environment easily.
 */
@Component({
  selector: 'sat-platform-nav-switcher',
  host: {
    '[attr.tabindex]': '-1',
  },
  imports: [
    MatRipple,
    MatButtonModule,
    MatIconModule,
    MatTooltip,
    CdkMenuModule,
    SatPlatformNavEnvironmentSwitcherItem,
    TranslatePipe,
  ],
  templateUrl: './platform-nav-environment-switcher.html',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class SatPlatformNavEnvironmentSwitcher {
  /**
   * The currently selected environment.
   * This should match the `value` property of one of the provided environment objects.
   */
  readonly value = input.required<string>();

  /**
   * The available environments.
   * This input is required and should be provided with an array of environment objects.
   */
  readonly environments = input.required<SatPlatformNavEnvironmentType[]>();

  /**
   * Denotes whether the switcher is disabled.
   */
  readonly disabled = input<boolean, unknown>(false, { transform: booleanAttribute });

  /**
   * An event emitted when the environment is changed.
   * The value emitted is the currently selected environment.
   * @type SatPlatformNavEnvironmentType
   */
  readonly environmentChange = output<SatPlatformNavEnvironmentType>();

  /** @internal */
  readonly satPlatformNavStateService = inject(SatPlatformNavState);

  /**
   * @internal User selection takes precedence over the initial selection.
   */
  readonly selectedEnv = linkedSignal<SatPlatformNavEnvironmentType | undefined>(() => {
    return this.environments()?.find(
      (env: SatPlatformNavEnvironmentType) => env.value === this.value(),
    );
  });

  /**
   * @internal
   * Handle option selection
   */
  onSelect(environment: SatPlatformNavEnvironmentType): void {
    if (!this.disabled()) {
      const wasSelected = this.selectedEnv()?.value === environment.value;

      const isEnvironmentInList = this.environments().some(
        (env: SatPlatformNavEnvironmentType) => env.value === environment.value,
      );

      if (isEnvironmentInList && !wasSelected) {
        this.selectedEnv.set(environment);
        this._propagateChanges();
      }
    }
  }

  // Propagates the selected environment change to the output event.
  private _propagateChanges(): void {
    const selectedEnv = this.selectedEnv();
    if (selectedEnv) {
      this.environmentChange.emit(selectedEnv);
    }
  }
}
