import { ObserversModule } from '@angular/cdk/observers';
import { ChangeDetectionStrategy, Component, inject, signal } from '@angular/core';
import { MatTooltip } from '@angular/material/tooltip';

import { SatPlatformNavInitials } from '../../platform-nav-initials';
import { SatPlatformNavState } from '../../services/platform-nav-state';
import { SatPlatformNavAppIcon } from '../platform-nav-app-icon/platform-nav-app-icon';

/**
 * This component displays a clickable user identity block, such as a name along with an avatar that can have initials or user profile image in the platform sidebar’s user section. It also has a responsive behavior based on the collapsed state of the sidebar.
 *
 * Key features:
 * - Typically used to show user info like names, emails, or avatar initials.
 * - Styled for sidebar placement within sat-platform-nav-user.
 */
@Component({
  selector: 'sat-platform-nav-user-profile',
  template: `
    <button
      aria-haspopup="menu"
      id="sat-platform-nav-user-profile"
      class="sat-platform-nav-item"
      [matTooltip]=" service.collapsed() ? (profileNameText() ?? profileName.innerText) : null"
      [attr.aria-label]="profileNameText() ?? profileName.innerText"
      matTooltipPosition="right"
    >
      <span class="sat-platform-nav-icon">
        <ng-container #avatarContainer>
          <ng-content select="mat-icon, img"></ng-content>
        </ng-container>
        @if (
          avatarContainer?.previousElementSibling?.localName !== 'mat-icon' &&
          avatarContainer?.previousElementSibling?.localName !== 'img'
        ) {
          <sat-platform-nav-app-icon class="sat-platform-nav-user-avatar">
            {{ profileNameText() ?? profileName.innerText | satPlatformNavInitials }}
          </sat-platform-nav-app-icon>
        }
      </span>
      <p #profileName
        class="sat-platform-nav-item-label"
        [class.sat-platform-nav-hidden]="service.collapsed()"
        (cdkObserveContent)="profileNameChanged($event)"
      >
        <ng-content></ng-content>
      </p>
    </button>
  `,
  imports: [SatPlatformNavAppIcon, SatPlatformNavInitials, ObserversModule, MatTooltip],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class SatPlatformNavUserProfile {
  /** @internal */
  readonly service = inject(SatPlatformNavState);

  /**
   * @internal
   * The text content of the profile name, used for tooltip and fallback initials.
   */
  readonly profileNameText = signal<string | undefined>(undefined);

  /** @internal */
  profileNameChanged(event: MutationRecord[]): void {
    const text = event[0]?.target?.textContent;
    if (text) {
      this.profileNameText.set(text);
    }
  }
}
