import { ChangeDetectionStrategy, Component, signal } from '@angular/core';
import { MatButtonModule } from '@angular/material/button';

/**
 * @internal
 * This component provides a "Skip to main content" link that allows users to bypass navigation links and go directly to the main content of the page.
 * It is particularly useful for improving accessibility for keyboard and screen reader users.
 */
@Component({
  selector: 'sat-skip-to-content',
  template: `
    <a
      mat-raised-button
      href="#main-content"
      tabindex="0"
      class="sat-skip-to-content-button"
      [class.sat-skip-to-content-button-visible]="visible()"
      (focus)="display()"
      (blur)="hide()"
    >
      Skip to main content
    </a>
  `,
  styles: [
    '.sat-skip-to-content-button { position: absolute; top: -100%; left: -100%; z-index: 2000; opacity: 0; }',
    '.sat-skip-to-content-button-visible { position: fixed; top: 24px; left: 24px; opacity: 100; }',
  ],
  imports: [MatButtonModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class SatSkipToContent {
  /** @internal */
  readonly visible = signal<boolean>(false);

  /** @internal */
  display() {
    this.visible.set(true);
  }

  /** @internal */
  hide() {
    this.visible.set(false);
  }
}
